import java.util.Scanner;

public class Main {
    public static long gcdCustom(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static long lcmCustom(long a, long b) {
        return a / gcdCustom(a, b) * b;
    }

    static class FractionType {
        long numerator;
        long denominator;

        FractionType(long numerator, long denominator) {
            this.numerator = numerator;
            this.denominator = denominator;
        }
    }

    public static FractionType getAbs(FractionType f) {
        return new FractionType(Math.abs(f.numerator), f.denominator);
    }

    public static int compareFraction(FractionType a, FractionType b) {
        long l = lcmCustom(a.denominator, b.denominator);
        long na = a.numerator * (l / a.denominator);
        long nb = b.numerator * (l / b.denominator);
        if (na == nb) return 0;
        return (na < nb) ? -1 : 1;
    }

    public static FractionType subtractFraction(FractionType a, FractionType b) {
        long l = lcmCustom(a.denominator, b.denominator);
        long na = a.numerator * (l / a.denominator);
        long nb = b.numerator * (l / b.denominator);
        long res_num = na - nb;
        long g = gcdCustom(Math.abs(res_num), l);
        return new FractionType(res_num / g, l / g);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();
        sc.close();

        long g = gcdCustom(x, y);
        x /= g;
        y /= g;
        FractionType xy = new FractionType(x, y);
        FractionType min_diff = new FractionType(1000000000000L, 1);
        FractionType min_val = new FractionType(0, 0);

        for (long b = 1; b <= n; ++b) {
            long l = 0, r = 1000000;
            double maxv = (double) x / y + (double) min_diff.numerator / min_diff.denominator + 2;
            maxv *= b;
            r = (long) maxv;
            while (l <= r) {
                long mid = l + (r - l) / 2;
                FractionType candidate = new FractionType(mid, b);
                FractionType diff = getAbs(subtractFraction(xy, candidate));
                int cmp = compareFraction(diff, min_diff);
                if (cmp == 0) {
                    if (candidate.denominator < min_val.denominator)
                        min_val = candidate;
                    else if (candidate.denominator == min_val.denominator && candidate.numerator < min_val.numerator)
                        min_val = candidate;
                } else if (cmp < 0) {
                    min_diff = diff;
                    min_val = candidate;
                }
                if (compareFraction(candidate, xy) < 0)
                    l = mid + 1;
                else
                    r = mid - 1;
            }
        }
        System.out.println(min_val.numerator + "/" + min_val.denominator);
    }
}
